#!/usr/bin/env node
/**
 * fix-fabricated-counties.js — MASTER-PLAN Defect B, stage 2.
 *
 * The scraper seed data was generated by appending " County" to the city name, so
 * ~2,000 configured library entries carry values like "Bainbridge County" or
 * "Alamo County" that are not real counties. getCountyCentroid() returns null for
 * them, which kills the county tier of the geocoding chain and drops those events
 * on the STATE centroid.
 *
 * This replaces those values with the real county, resolved from an authoritative
 * join built in scripts/data/city-county-map.json:
 *   - US Census Bureau 2023 National Counties Gazetteer  (county FIPS -> name + centroid)
 *   - GeoNames US populated places                       (city -> county FIPS)
 * Stage 1 of the fix completed scrapers/utils/county-centroids.js from the same Census
 * file, which on its own resolved 939 entries whose county name was already correct but
 * simply absent from that dataset. Run stage 1 first; this handles what remains.
 *
 * SAFETY RULES, each of which exists because of a real failure in this project:
 *  - Only entries whose county does NOT currently resolve are touched. Entries that
 *    already resolve are left alone even when the dataset disagrees, because ~292 of
 *    those disagreements are Connecticut's 2022 switch from counties to Planning
 *    Regions, not errors — rewriting them would be a regression, not a fix.
 *  - Comments are blanked POSITION-PRESERVINGLY before parsing, so edits land in the
 *    real config array and never in an AUTO-GENERATED header comment. A previous
 *    WordPress-MD patch edited the comment instead of the code because String.replace
 *    takes the first match and the comment precedes the array.
 *  - Dry run by default; --save to write. Read the samples before saving.
 *
 * Usage:
 *   node scripts/fix-fabricated-counties.js            # dry run
 *   node scripts/fix-fabricated-counties.js --save
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const MAP_FILE = path.join(__dirname, 'data', 'city-county-map.json');
const save = process.argv.includes('--save');

const reg = require(path.join(ROOT, 'scrapers', 'scraper-registry.js'));
const { getCountyCentroid } = require(path.join(ROOT, 'scrapers', 'utils', 'county-centroids.js'));

if (!fs.existsSync(MAP_FILE)) {
  console.error(`Missing ${path.relative(ROOT, MAP_FILE)} — rebuild it from the Census + GeoNames sources.`);
  process.exit(1);
}
const cityMap = JSON.parse(fs.readFileSync(MAP_FILE, 'utf8'));

// Must match the normalisation used when the map was built: configs write "St. Augustine"
// and "Mt. Juliet" where GeoNames writes "Saint Augustine" / "Mount Juliet".
const norm = s => String(s || '').toLowerCase()
  .replace(/[.'’]/g, ' ').replace(/\s+/g, ' ')
  .replace(/\bst\b/g, 'saint').replace(/\bste\b/g, 'sainte')
  .replace(/\bmt\b/g, 'mount').replace(/\bft\b/g, 'fort')
  .replace(/\s+/g, ' ').trim();

/**
 * Replace comments with spaces rather than deleting them, so every character index in
 * the returned string still maps to the same index in the original source. That is what
 * lets us parse from a comment-free view and splice into the real file safely.
 */
function blankComments(src) {
  return src
    .replace(/\/\*[\s\S]*?\*\//g, m => m.replace(/[^\n]/g, ' '))
    .replace(/^([ \t]*)\/\/[^\n]*$/gm, m => ' '.repeat(m.length));
}

/**
 * Quote-aware string matcher that respects backslash escapes.
 *
 * A naive /'([^']*)'/ stops at the first apostrophe, which in this codebase is often an
 * ESCAPED one inside the value: `county: 'Prince George\'s County'`. Parsing with the
 * naive form yields "Prince George\", which does not resolve, so a correct entry looks
 * broken and gets "fixed"; writing with it replaced only up to that apostrophe and
 * produced `'Prince George's's County'`, a syntax error. Both happened on the first
 * run of this script and broke 7 files, caught by node -c before anything was committed.
 */
const QUOTED = `(?:'((?:[^'\\\\]|\\\\.)*)'|"((?:[^"\\\\]|\\\\.)*)")`;
const field = n => new RegExp(`["']?${n}["']?\\s*:\\s*${QUOTED}`);
const unescape = s => String(s).replace(/\\(.)/g, '$1');
const val = m => (m ? unescape(m[1] !== undefined ? m[1] : m[2]) : '');
// Escape a value for embedding in a single-quoted JS string literal.
const escapeSingle = s => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");

const activeStates = reg.getActiveStates();
const all = { ...reg.SCRAPERS, ...(reg.MACARONI_SCRAPERS || {}) };

// One file can back several registry keys; only visit each file once.
const files = new Map();
Object.entries(all).forEach(([key, sc]) => {
  if (!sc.file || !reg.isScraperActive(sc, activeStates)) return;
  const rel = String(sc.file).replace(/^\.\//, '');
  if (!files.has(rel)) files.set(rel, sc.state || '');
});

let totalChanged = 0, totalSkippedNoCity = 0, totalSkippedNoMatch = 0, filesChanged = 0;
const samples = [];
const perFile = [];

for (const [rel, defaultState] of files) {
  const abs = path.join(ROOT, 'scrapers', rel);
  if (!fs.existsSync(abs)) continue;
  const src = fs.readFileSync(abs, 'utf8');
  const view = blankComments(src);

  const edits = [];
  const objRe = /\{[^{}]*\}/g;
  let o;
  while ((o = objRe.exec(view))) {
    const start = o.index, end = start + o[0].length;
    const raw = src.slice(start, end);            // identical span in the real source

    const nm = field('name').exec(raw); if (!nm) continue;
    const countyM = field('county').exec(raw); if (!countyM) continue;
    const county = val(countyM);
    const city = val(field('city').exec(raw));
    const state = (val(field('state').exec(raw)) || defaultState || '').toUpperCase();
    if (!county || !state || state === 'MULTI') continue;

    if (getCountyCentroid(county, state)) continue;      // already fine — never touch
    if (!city) { totalSkippedNoCity++; continue; }

    const truth = cityMap[`${norm(city)}|${state}`];
    if (!truth) { totalSkippedNoMatch++; continue; }
    if (!getCountyCentroid(truth, state)) { totalSkippedNoMatch++; continue; }  // must actually resolve

    // Splice only the county VALUE. Always emit a single-quoted literal with the value
    // properly escaped, matching the file style, rather than trying to detect and reuse
    // the original quoting — that detection is what mangled escaped apostrophes before.
    const cStart = start + countyM.index;
    const cText = countyM[0];
    const prefix = cText.slice(0, cText.indexOf(':') + 1);
    const spacing = (/:(\s*)/.exec(cText) || [, ' '])[1];
    const replacement = `${prefix}${spacing}'${escapeSingle(truth)}'`;
    edits.push({ at: cStart, len: cText.length, text: replacement });

    if (samples.length < 20) samples.push(`${rel}: ${val(nm)} (${city}, ${state})  "${county}" -> "${truth}"`);
  }

  if (!edits.length) continue;
  // Apply back-to-front so earlier offsets stay valid.
  let out = src;
  edits.sort((a, b) => b.at - a.at).forEach(e => {
    out = out.slice(0, e.at) + e.text + out.slice(e.at + e.len);
  });

  perFile.push([rel, edits.length]);
  totalChanged += edits.length;
  filesChanged++;
  if (save) fs.writeFileSync(abs, out);
}

console.log(`\n${save ? 'WROTE' : 'DRY RUN'} — fabricated county values replaced: ${totalChanged} across ${filesChanged} files`);
console.log(`  skipped, entry has no city field : ${totalSkippedNoCity}`);
console.log(`  skipped, no confident city match : ${totalSkippedNoMatch}`);
console.log('\nby file:');
perFile.sort((a, b) => b[1] - a[1]).forEach(([f, n]) => console.log(`  ${String(n).padStart(5)}  ${f}`));
console.log('\nsamples:');
samples.forEach(s => console.log(`  ${s}`));
if (!save) console.log('\n(dry run — re-run with --save to write)');
